#[test]
fn test_every_claimed_row_of_bidi_character_test_txt() {
    let f: &[u8] = &crate::testport::test_file("bidi/conformance.txt")[..];
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let want_lv: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let want_vis: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let end: i32 = crate::port::blob_len(f);
    let mut pos: i32 = 0;
    let mut line: i32 = 0;
    let mut rows: i32 = 0;
    let mut e: i32 = 0;
    let mut s1: i32 = 0;
    let mut s2: i32 = 0;
    let mut n: i32 = 0;
    let mut o: i32 = 0;
    let mut k: i32 = 0;
    let mut badl: i32 = 0;
    let mut badv: i32 = 0;
    while pos < end {
        line += 1;
        e = bt_nl(f, pos);
        if (pos < e) && (crate::port::blob_u8(f, pos) != 35) {
            rows += 1;
            s1 = bt_next(f, pos, e, 59);
            s2 = bt_next(f, s1 + 1, e, 59);
            crate::port::cells_drop(ar, 0);
            n = bt_nums(f, pos, s1, 16, ar);
            bt_nums(f, s1 + 1, s2, 10, want_lv);
            bt_nums(f, s2 + 1, e, 10, want_vis);
            o = bd_order_of(ar, 0, n);
            badl = 0;
            badv = 0;
            k = 0;
            while k < n {
                if crate::port::cells_at(ar, (o - n) + k) != crate::port::cells_at(want_lv, k) {
                    badl += 1;
                }
                if crate::port::cells_at(ar, o + k) != crate::port::cells_at(want_vis, k) {
                    badv += 1;
                }
                k += 1;
            }
            crate::testport::assert_eq_at(badl, 0, "characters with a wrong level", line);
            crate::testport::assert_eq_at(badv, 0, "positions in the wrong visual order", line);
        }
        pos = e + 1;
    }
    crate::testport::assert_that(rows > 1000, "the corpus has its rows");
}
